NOTES={
"concrete-calculator":("concrete-80lb","Based on premixed concrete bags (e.g. Quikrete, Sakrete): 80 lb ≈ 0.60 cu ft, 60 lb ≈ 0.45, 40 lb ≈ 0.30. Brands vary slightly — check the label."),
"paint-calculator":("interior-paint","Based on about 350 sq ft per gallon, typical for interior latex paint (e.g. Behr, Sherwin-Williams). Check the coverage on your can."),
"mulch-calculator":("bagged-mulch","Based on 2 and 3 cu ft bags, the common bagged mulch sizes. Check the bag label."),
"gravel-calculator":("gravel-bag","Based on 0.5 cu ft bags and about 1.4 tons per cu yd. Ask your supplier for the exact density."),
"tile-calculator":("tile-box","Based on 15 sq ft per box. Box coverage varies by tile — check the carton."),
"drywall-calculator":("drywall-compound","Based on standard 4×8 / 4×12 ft panels and ready-mix all-purpose joint compound (e.g. USG Sheetrock) at ~10 gal per 1,000 sq ft. Check the label."),
"flooring-calculator":("flooring-box","Based on 20 sq ft per box, typical for laminate and vinyl plank. Check the carton."),
"roofing-calculator":("shingles","Based on 3 bundles per square, standard for architectural shingles (e.g. GAF, Owens Corning). Check the wrapper."),
"deck-board-calculator":("deck-board","Based on 5/4×6 deck boards (5.5 in actual width) with 1/8 in gaps. Check your board's actual width."),
"fence-calculator":("fence-post-concrete","Concrete based on about two 50 lb bags of fast-setting concrete per post (e.g. Quikrete Fast-Setting). Check the bag label."),
"insulation-calculator":("insulation","Default R-3.2 per inch is typical for blown cellulose. Use the coverage chart on your bag for the bag count."),
"wallpaper-calculator":("wallpaper-roll","Based on a standard US double roll, 20.5 in × 33 ft. Check the label."),
"grout-calculator":("sanded-grout","Based on sanded cement grout (e.g. Polyblend, Mapei) at ~0.058 lb per cu in. Check the bag's coverage chart."),
"paver-calculator":("paver","Based on standard 4×8 in brick-style pavers. Check the pallet label for coverage."),
"topsoil-calculator":("topsoil-bag","Based on 0.75 cu ft bags of topsoil, a common store size. Check the bag label."),
"sand-calculator":("sand-bag","Based on 50 lb bags of all-purpose sand and about 1.35 tons per cu yd. Check the bag label."),
"asphalt-calculator":("asphalt","Based on hot-mix asphalt at about 145 lb per cu ft. Ask your paving contractor for their mix."),
"sod-grass-seed-calculator":("sod-seed","Based on 2×5 ft sod pieces and ~450 sq ft pallets. Pallet size and seed rate vary — check with your supplier and the seed bag."),
}
