def cat(k): return next(c for c,ks in CATS.items() if k in ks)
def svg(c,s=24): return f'<svg width="{s}" height="{s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICON[c]}</svg>'
