LOGO='<svg width="32" height="32" viewBox="0 0 32 32" aria-hidden="true"><defs><linearGradient id="pmg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#14b8a6"/><stop offset="1" stop-color="#0f766e"/></linearGradient></defs><rect width="32" height="32" rx="9" fill="url(#pmg)"/><path d="M5 15.5L16 7l11 8.5" stroke="#fff" stroke-width="2.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M8.5 15v10h15V15" fill="#fff"/><rect x="7" y="17.5" width="18" height="2.2" rx="1" fill="#f59e0b"/><path d="M11 19.7V25M16 19.7V25M21 19.7V25" stroke="#0f766e" stroke-width="1.6"/></svg>'
css="""*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#1f2937;background:#f8fafc;line-height:1.65;font-size:17px}a{color:#0f766e}.w{max-width:1120px;margin:auto;padding:0 18px}
header{background:#fff;border-bottom:1px solid #e5e7eb;position:sticky;top:0;z-index:5}header .w{display:flex;align-items:center;justify-content:space-between;height:60px}.logo{display:flex;align-items:center;gap:9px;font-weight:800;font-size:20px;color:#0f172a;text-decoration:none}.logo b{color:#0f766e}nav a{margin-left:18px;color:#374151;text-decoration:none;font-weight:600;font-size:15px}nav a:hover{color:#0f766e}
.hero{background:linear-gradient(135deg,#0f766e,#115e59 60%,#134e4a);color:#fff;padding:52px 0 60px}.hero h1{font-size:clamp(28px,5vw,44px);line-height:1.15;margin:0 0 12px}.hero p{opacity:.9;max-width:640px;margin:0 0 24px}.search{display:flex;background:#fff;border-radius:12px;max-width:560px;padding:4px 14px;align-items:center;gap:8px;box-shadow:0 10px 30px rgba(0,0,0,.18)}.search input{border:0;outline:0;font-size:17px;padding:12px 0;width:100%;color:#111}.search svg{color:#6b7280;flex:none}
h2.sec{font-size:24px;margin:40px 0 16px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px}.card{display:flex;gap:14px;background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;text-decoration:none;color:inherit;transition:box-shadow .15s,transform .15s}.card:hover{box-shadow:0 8px 24px rgba(15,23,42,.08);transform:translateY(-2px)}.ic{flex:none;width:44px;height:44px;border-radius:11px;display:grid;place-items:center}.card h3{margin:0 0 4px;font-size:17px;color:#0f172a}.card p{margin:0;font-size:14px;color:#6b7280;line-height:1.5}.tag{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.04em}
.crumb{font-size:14px;color:#6b7280;margin:22px 0 6px}.crumb a{color:#6b7280}.th1{font-size:clamp(26px,4.5vw,38px);line-height:1.2;margin:0 0 8px;color:#0f172a}.lead{color:#4b5563;margin:0 0 22px}
.tool{display:grid;gap:20px;grid-template-columns:1fr}@media(min-width:860px){.tool{grid-template-columns:1.1fr .9fr}}.calc,.res{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:22px}.calc label{display:block;font-weight:600;font-size:15px;margin:12px 0 5px;color:#374151}.calc input{width:100%;padding:12px 14px;font-size:17px;border:1px solid #d1d5db;border-radius:10px;background:#f9fafb}.calc input:focus{outline:2px solid #0f766e;border-color:#0f766e;background:#fff}.btn{margin-top:18px;width:100%;padding:14px;font-size:17px;font-weight:700;background:#0f766e;color:#fff;border:0;border-radius:10px;cursor:pointer}.btn:hover{background:#115e59}
.res{background:#0f172a;color:#e5e7eb;border:0;align-self:start}.res h2{margin:0 0 10px;font-size:18px;color:#fff}.res table{width:100%;border-collapse:collapse}.res td{padding:11px 0;border-bottom:1px solid #1e293b;font-size:15px}.res td:last-child{text-align:right;font-weight:800;font-size:19px;color:#5eead4}.basis-note{font-size:12px;color:#64748b;margin:6px 0 0;line-height:1.45}.note{font-size:13px;color:#94a3b8;margin:12px 0 0}
.guide{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:8px 26px 20px;margin:24px 0;max-width:760px}.guide h2{font-size:22px;margin:26px 0 8px;color:#0f172a}.guide li{margin:4px 0}.slot:empty{display:none}.slot{border:1px dashed #cbd5e1;border-radius:12px;padding:14px;margin:20px 0;color:#64748b;font-size:14px}
footer{background:#0f172a;color:#94a3b8;margin-top:56px;padding:36px 0;font-size:14px}footer .w{display:grid;gap:22px;grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}footer a{color:#cbd5e1;text-decoration:none;display:block;margin:4px 0}footer h4{color:#fff;margin:0 0 8px}.page{max-width:760px}
@media(max-width:640px){nav a.hide{display:none}.hero{padding:36px 0 42px}body{font-size:16px}}"""
head_nav=f"<header><div class='w'><a class='logo' href='/'>{LOGO}<span>Porch<b>Math</b></span></a><nav><a href='/#all'>Calculators</a><a class='hide' href='/about/'>About</a><a class='hide' href='/contact/'>Contact</a></nav></div></header>"
foot="<footer><div class='w'><div><a class='logo' style='color:#fff' href='/'>"+LOGO+"<span>Porch<b>Math</b></span></a><p>Free, fast material calculators for DIY home projects. Formulas shown on every page.</p></div>"+"".join(f"<div><h4>{c}</h4>"+"".join(f"<a href='/{k}/'>{tools[k]['h']}</a>" for k in ks[:5])+"</div>" for c,ks in CATS.items())+"<div><h4>PorchMath</h4><a href='/about/'>About</a><a href='/privacy/'>Privacy Policy</a><a href='/contact/'>Contact</a></div></div><div class='w'><p>Estimates only—confirm quantities with your supplier and local building codes. © 2026 PorchMath</p></div></footer>"
def page(path,title,desc,body,schema):
    os.makedirs("dist/"+path,exist_ok=True)
    open(f"dist/{path}/index.html".replace("//","/"),"w").write(f"""<!doctype html><html lang="en"><head><meta charset="utf-8">{GSC}<meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="{SITE}/{path}{'/' if path else ''}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta name="theme-color" content="#0f766e"><meta property="og:site_name" content="PorchMath"><meta property="og:type" content="website"><meta property="og:url" content="{SITE}/{path}{'/' if path else ''}"><link rel="icon" href="/favicon.svg"><style>{css}</style><script type="application/ld+json">{json.dumps(schema)}</script></head><body>{head_nav}{body}{foot}</body></html>""")
def card(k):
    c=cat(k);fg,bg=CATC[c];v=tools[k]
    return f"<a class='card' href='/{k}/' data-s='{html.escape((v['h']+' '+v['d']+' '+c).lower())}'><span class='ic' style='background:{bg};color:{fg}'>{svg(c)}</span><span><span class='tag' style='color:{fg}'>{c}</span><h3>{v['h']}</h3><p>{v['d'][:96].rsplit(' ',1)[0]}…</p></span></a>"
for k,v in tools.items():
    c=cat(k)
    inputs="".join(f"<label for='{i}'>{l}</label><input id='{i}' type='number' step='any' inputmode='decimal' value='{d}'>" for i,l,d in v['f'])
    js=f"function U(x){{return Math.ceil(+(+x).toFixed(6))}}function c(){{var "+",".join(f"{i}=+document.getElementById('{i}').value" for i,_,_ in v['f'])+f";if([{','.join(i for i,_,_ in v['f'])}].some(function(x){{return !isFinite(x)||x<0}}))return [['Please enter non-negative numbers','—']];return (function(){{{v['js'].replace('Math.ceil(','U(')}}})().map(function(x){{var s=String(x[1]);return [x[0],/NaN|Infinity/.test(s)?'—':x[1]]}})}}function run(){{document.getElementById('r').innerHTML=c().map(function(x){{return '<tr><td>'+x[0]+'</td><td><b>'+x[1]+'</b></td></tr>'}}).join('')}}document.querySelectorAll('.calc input').forEach(function(e){{e.addEventListener('input',run)}});run();"
    n=NOTES.get(k);bn=f"<p class='basis-note' data-product='{n[0]}'>{n[1]}</p>" if n else ''
    relc="".join(card(x) for x in CATS[c] if x!=k)
    body=f"<main class='w'><div class='crumb'><a href='/'>Home</a> › <a href='/#all'>{c}</a></div><h1 class='th1'>{v['h']}</h1><p class='lead'>{v['d']}</p><div class='tool'><form class='calc' onsubmit='run();return false'>{inputs}<button class='btn'>Calculate</button></form><div class='res' aria-live='polite'><h2>Your estimate</h2><table id='r'></table><p class='note'>Results update as you type. Round up when ordering.</p>{bn}</div></div><div class='slot'><!-- AFFILIATE_SLOT: recommended products (Amazon Associates) – add real links after approval --></div><article class='guide'>{v['g']}</article><div class='slot'><!-- AD_SLOT --></div><h2 class='sec'>Related calculators</h2><div class='grid'>{relc}</div></main><script>{js}</script>"
    page(k,v['t'],v['d'],body,{"@context":"https://schema.org","@type":"WebApplication","name":v['h'],"url":f"{SITE}/{k}/","applicationCategory":"UtilitiesApplication","operatingSystem":"Any","offers":{"@type":"Offer","price":"0","priceCurrency":"USD"},"description":v['d']})
srch='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="M21 21l-5-5"/></svg>'
home=f"<section class='hero'><div class='w'><h1>Know exactly how much to buy.</h1><p>Free calculators for concrete, paint, flooring, roofing, fencing and more—with the formulas and pro tips shown, so you can check the math.</p><label class='search'>{srch}<input id='q' type='search' placeholder='Search 20 calculators… e.g. “paint”' aria-label='Search calculators'></label></div></section><main class='w'><div id='pop'><h2 class='sec'>Popular calculators</h2><div class='grid'>"+"".join(card(k) for k in POP)+"</div></div><div id='all'>"+"".join(f"<section class='cat'><h2 class='sec'>{c}</h2><div class='grid'>"+"".join(card(k) for k in ks)+"</div></section>" for c,ks in CATS.items())+"<p id='none' hidden>No calculator matches. Try another word.</p></div></main><script>var q=document.getElementById('q');q.addEventListener('input',function(){var t=q.value.toLowerCase().trim(),n=0;document.getElementById('pop').hidden=!!t;document.querySelectorAll('#all .cat').forEach(function(s){var m=0;s.querySelectorAll('.card').forEach(function(c){var ok=c.dataset.s.indexOf(t)>-1;c.hidden=!ok;if(ok)m++});s.hidden=!m;n+=m});document.getElementById('none').hidden=n>0})</script>"
page("","PorchMath – Free Home Improvement Calculators","Free calculators for concrete, paint, flooring, roofing, fencing, mulch, gravel and more. Fast, mobile-friendly, with how-to guides.",home,{"@context":"https://schema.org","@type":"WebSite","name":"PorchMath","url":SITE+"/"})
def sp(p,t,d,b): page(p,t+" – PorchMath",d,f"<main class='w page'><h1 class='th1' style='margin-top:28px'>{t}</h1><div class='guide'>{b}</div></main>",{"@context":"https://schema.org","@type":"WebPage","name":t,"url":f"{SITE}/{p}/"})
sp("about","About PorchMath","About PorchMath: free home improvement material calculators.","<p>PorchMath is a free collection of material calculators for homeowners and DIYers. Each tool shows the formula it uses, a worked example and practical tips, so you can understand—and double-check—every estimate.</p><h2>How we build our calculators</h2><p>Formulas are standard geometry (area and volume) combined with typical material data such as bag yields, coverage rates and densities. Where numbers vary by product, the calculator lets you enter the value from your product label.</p><h2>Accuracy</h2><p>Results are estimates. Always confirm quantities with your supplier and follow local building codes and manufacturer instructions.</p>")
sp("privacy","Privacy Policy","PorchMath privacy policy.","<p><i>Last updated: October 20, 2026</i></p><p>PorchMath calculators run entirely in your browser. The numbers you enter are not sent to or stored on our servers.</p><h2>Hosting and logs</h2><p>The site is hosted on Cloudflare Pages, which may process technical data such as IP addresses for security and performance, as described in Cloudflare's privacy policy.</p><h2>Cookies and advertising</h2><p>We do not currently set cookies. In the future we may show ads (for example via Google AdSense). Third-party vendors, including Google, may then use cookies to serve ads based on your prior visits to this and other websites. Google's use of advertising cookies enables it and its partners to serve ads based on your visits. You can opt out of personalized advertising at <a href='https://adssettings.google.com'>Google Ads Settings</a> or <a href='https://www.aboutads.info'>aboutads.info</a>. This policy will be updated before any such service is enabled.</p><h2>Affiliate links</h2><p>Some pages may in future contain affiliate links (for example Amazon Associates). As an Amazon Associate we would earn from qualifying purchases, at no extra cost to you. Affiliate links will be clearly disclosed.</p><h2>Contact</h2><p>Questions about this policy: email <a href='mailto:Duylinh30190@gmail.com'>Duylinh30190@gmail.com</a> or see our <a href='/contact/'>Contact page</a>.</p>")
sp("contact","Contact","Contact PorchMath.","<p>Found a bug, a wrong number, or want a new calculator? We'd love to hear from you.</p><p>Email: <a href='mailto:Duylinh30190@gmail.com'>Duylinh30190@gmail.com</a></p><p>You can also <a href='https://github.com/yamakaru/porchmath/issues'>open an issue on GitHub</a>.</p>")
open("dist/robots.txt","w").write(f"User-agent: *\nAllow: /\nSitemap: {SITE}/sitemap.xml\n")
open("dist/sitemap.xml","w").write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+"".join(f"<url><loc>{SITE}/{p}</loc></url>" for p in ["","about/","privacy/","contact/"]+[k+"/" for k in tools])+"</urlset>")
open(f"dist/{INDEXNOW_KEY}.txt","w").write(INDEXNOW_KEY)

open("dist/favicon.svg","w").write(LOGO.replace('width="32" height="32" ','xmlns="http://www.w3.org/2000/svg" ').replace(' aria-hidden="true"',''))

# Host canonicalisation: *.pages.dev and www -> apex (301, path + query preserved)
open("dist/_worker.js","w").write("""export default{async fetch(req,env){const u=new URL(req.url),h=u.hostname,apex=new URL(SITE).hostname;if(h!==apex&&h!=='localhost'&&(h.endsWith('.pages.dev')||h==='www.'+apex)){return Response.redirect(SITE+u.pathname+u.search,301)}return env.ASSETS.fetch(req)}};""".replace("SITE+","'"+SITE+"'+").replace("new URL(SITE)","new URL('"+SITE+"')"))
